# Try: Fill 1s in col 2 using vertical propagation from nearest non-1 above or below
grid = [
    [5, 6, 6, 1, 1, 1],
    [5, 5, 5, 1, 1, 1],
    [5, 5, 9, 1, 1, 1],
    [6, 9, 1, 1, 1, 1],
    [5, 6, 1, 1, 1, 1],
    [2, 5, 1, 1, 1, 1],
    [6, 9, 1, 1, 1, 1],
    [9, 2, 1, 1, 1, 1],
    [5, 5, 9, 1, 1, 1]
]

filled = [row[:] for row in grid]

for r in range(9):
    if filled[r][2] == 1:
        # Look up and down for nearest non-1
        val_up = None
        for rr in range(r-1, -1, -1):
            if filled[rr][2] != 1:
                val_up = filled[rr][2]
                break

        val_down = None
        for rr in range(r+1, 9):
            if filled[rr][2] != 1:
                val_down = filled[rr][2]
                break

        # Choose: prefer up, otherwise down, otherwise keep 1
        if val_up:
            filled[r][2] = val_up
        elif val_down:
            filled[r][2] = val_down

print("Vertical fill:")
for row in filled:
    print(row[:3])

output = []
for r in range(9):
    output.append(filled[r][:3] + filled[r][:3])

print("\nOutput:")
for row in output:
    print(row)

# Check: rows with same (c0,c1) prefix should eventually have same c2 after completion
grid = [
    [5, 6, 6, 1, 1, 1],
    [5, 5, 5, 1, 1, 1],
    [5, 5, 9, 1, 1, 1],
    [6, 9, 1, 1, 1, 1],
    [5, 6, 1, 1, 1, 1],
    [2, 5, 1, 1, 1, 1],
    [6, 9, 1, 1, 1, 1],
    [9, 2, 1, 1, 1, 1],
    [5, 5, 9, 1, 1, 1]
]

groups = {}
for r in range(9):
    key = (grid[r][0], grid[r][1])
    if key not in groups:
        groups[key] = []
    groups[key].append(r)

print("Groups with their c2 values:")
all_c2_by_key = {}
for r in range(9):
    key = (grid[r][0], grid[r][1])
    c2 = grid[r][2]
    if key not in all_c2_by_key:
        all_c2_by_key[key] = []
    all_c2_by_key[key].append(c2)

for key, indices in all_c2_by_key.items():
    print(f"{key}: rows {indices}, c2s={all_c2_by_key[key]}")

# For each group, find the mode of non-1 values
filled = [row[:] for row in grid]
for key, indices in groups.items():
    c2_vals = [grid[i][2] for i in indices if grid[i][2] != 1]
    non_ones = [v for v in c2_vals if v != 1]

    if non_ones:
        mode = max(set(non_ones), key=lambda x: sum(1 for v in non_ones if v == x))
    else:
        mode = None

    print(f"\nGroup {key}: need to fill rows {[i for i in indices if grid[i][2]==1]}, mode={mode}")

    # If no info in group, try looking at OTHER groups with similar patterns
    if mode is None:
        # Look for any row with same c0 - use its c2
        c0 = key[0]
        for rr in range(9):
            if grid[rr][0] == c0 and grid[rr][2] != 1:
                mode = grid[rr][2]
                break

        if mode is None:
            # No help from same c0, use most common in entire column 2?
            col2_vals = [grid[i][2] for i in range(9) if grid[i][2] != 1]
            if col2_vals:
                mode = max(set(col2_vals), key=lambda x: sum(1 for v in col2_vals if v == x))
                print(f"  Using global column 2 mode: {mode}")

    # Apply fill
    for i in indices:
        if filled[i][2] == 1:
            filled[i][2] = mode

print("\nFinal filled left:")
for row in filled:
    print(row[:3])

output = []
for r in range(9):
    output.append(filled[r][:3] + filled[r][:3])

print("\nOutput:")
for row in output:
    print(row)
